require_once __DIR__.'/includes/module.php'; require_roles(['admin','admin_hrd']);$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT file_name,original_name FROM hrd_documents WHERE id=?');$q->execute([$id]);$doc=$q->fetch();if(!$doc){http_response_code(404);exit('Dokumen tidak ditemukan.');}$path=__DIR__.'/storage/hrd_documents/'.$doc['file_name'];if(!is_file($path)){http_response_code(404);exit('File tidak ditemukan.');}$ext=strtolower(pathinfo($doc['file_name'],PATHINFO_EXTENSION));$types=['pdf'=>'application/pdf','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','doc'=>'application/msword','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];header('Content-Type: '.($types[$ext]??'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.str_replace('"','',basename($doc['original_name'])).'"');readfile($path);exit;
